            paragraphs: [
              "TransLay verwendet KI-Übersetzungstechnologie. Wir streben hohe Übersetzungsqualität und hohe Layouttreue an, dennoch können Bedeutungsabweichungen, Längenänderungen, Umbrüche oder lokale Layoutunterschiede auftreten. Bei rechtlichen, finanziellen, medizinischen, vertraglichen oder sonstigen wichtigen Inhalten sollten Sie das Ergebnis vor der Verwendung selbst prüfen. Der Dienst kann außerdem wegen Wartung, Änderungen an vorgelagerten Plattformen, Netzwerkproblemen oder Drittanbieterdiensten vorübergehend verzögert, unterbrochen oder nicht verfügbar sein."
            ]
