              "Wenn Sie einen Plan oder Credits kaufen, verarbeiten wir die minimalen Bestell- und Aboinformationen, die zur Bestätigung Ihres Anspruchs erforderlich sind, etwa Zahlungsstatus, Bestellnummer, Kauf- oder Erstattungszeit und Abostatus. Vollständige Kartendaten werden von Paddle verarbeitet, nicht von uns gespeichert.",
              "Für Website-Sitzungen verwenden wir nur die minimalen Sitzungsinformationen, die für den Betrieb der offiziellen Website und der Abrechnungsseiten erforderlich sind. Cookies speichern nur eine undurchsichtige session id und keine direkt lesbaren Informationen wie E-Mail, Plan oder Kontingent."
