      privacy: {
        title: "Informativa sulla privacy di TransLay",
        last_updated: "Ultimo aggiornamento: 23 aprile 2026",
        intro: [
          "Consideriamo \"raccogliere meno, conservare meno, esporre meno\" un principio di base di TransLay. Quando usi TransLay, trattiamo solo le informazioni minime necessarie per far funzionare traduzione, accesso, abbonamento e assistenza post-vendita; ciò che non dovrebbe essere raccolto o conservato a lungo cerchiamo di non toccarlo. Questa informativa spiega come TransLay tratta tali informazioni."
        ],
        sections: [
          {
            title: "1. Il principio privacy che seguiamo",
            paragraphs: [
              "Il principio centrale di TransLay è semplice: trattiamo le informazioni necessarie solo per completare il servizio che avvii volontariamente. Non raccogliamo informazioni non collegate al servizio, non le usiamo per pubblicità, non creiamo profili utente e non facciamo analisi comportamentale. In particolare, per testo del documento, traduzioni, comments e notes, seguiamo un rigoroso principio di minimizzazione e non conserviamo questi contenuti a lungo in database, cache o log applicativi."
            ]
          },
          {
            title: "2. Quali informazioni minime trattiamo per fornire il servizio",
            paragraphs: [
              "Possiamo trattare informazioni di base dell'account Google, come identificativo dell'account, email, nome visualizzato e avatar, per confermare la tua identità, collegare abbonamenti e quote all'account corretto, mostrare l'account attualmente connesso e fornire assistenza post-vendita.",
              "Trattiamo i contenuti di Google Slides™ che scegli espressamente di tradurre solo dopo che avvii volontariamente un task di traduzione, e solo per completare quella traduzione e scriverne il risultato.",
              "Trattiamo inoltre le informazioni minime su task e quote necessarie per mostrare l'avanzamento, regolare l'uso delle quote, verificare problemi di fatturazione e fornire supporto, ad esempio Task ID, stato del task, uso delle pagine, timestamp e metadati limitati di diagnostica.",
              "Se acquisti un piano o crediti, trattiamo le informazioni minime su ordini e abbonamenti necessarie per confermare i tuoi diritti, ad esempio stato del pagamento, numero d'ordine, data di acquisto o rimborso e stato dell'abbonamento. I dati completi della carta sono trattati da Paddle e non vengono salvati da noi.",
              "Per le sessioni del sito web usiamo solo le informazioni minime necessarie al funzionamento del sito ufficiale e delle pagine di abbonamento. I cookie salvano solo un session id opaco e non memorizzano direttamente in chiaro email, piano o quota."
            ]
          },
          {
            title: "3. Cosa non conserviamo o raccogliamo",
            paragraphs: [
              "Non salviamo il testo in chiaro del contenuto dei tuoi documenti, dei risultati di traduzione, dei comments o delle notes in database, cache o log. Al termine del task di traduzione, questi contenuti vengono eliminati immediatamente dal nostro database e dalla cache e non restano come backup dei tuoi documenti; conserva quindi tu stesso i file tradotti.",
              "Se in seguito avvii di nuovo la traduzione dello stesso documento nella stessa lingua, la tratteremo come un nuovo task indipendente. Poiché non conserviamo i contenuti o le traduzioni precedenti, non riutilizziamo direttamente il risultato precedente e il nuovo task sarà fatturato integralmente secondo le regole del task corrente.",
              "Non usiamo le tue informazioni per pubblicità, attribuzione pubblicitaria, profilazione utente o analisi comportamentale. Non vendiamo i tuoi dati e non monitoriamo le tue attività su altri siti, documenti o prodotti solo perché usi TransLay.",
              "Non conserviamo il numero completo della carta, il numero completo del conto bancario o altre credenziali di pagamento complete. I pagamenti sono gestiti da Paddle; noi riceviamo solo le informazioni minime di esito necessarie per ordini e assistenza post-vendita."
            ]
          },
          {
            title: "4. Perché servono le autorizzazioni Google",
            paragraphs: [
              "TransLay è un add-on di Google Workspace™. Per funzionare correttamente in Google Slides™, richiediamo solo le autorizzazioni direttamente necessarie all'ambito attuale del prodotto.",
              "L'autorizzazione Google Slides™ serve a leggere il contenuto della presentazione da tradurre e a scrivere la traduzione nel file originale o nel file di destinazione. Senza questa autorizzazione, TransLay non può leggere il contenuto né completare la scrittura.",
              "L'autorizzazione Google Drive™ serve a individuare la presentazione corrente, creare copie di proprietà dell'utente nella modalità \"output in nuovo file\", collocare il file di destinazione nella posizione corretta e gestire gli accessi temporanei necessari durante l'esecuzione. Senza questa autorizzazione, alcuni flussi di copia e scrittura non possono funzionare stabilmente.",
              "L'autorizzazione Google Drive™ file ci aiuta a limitare per quanto possibile le operazioni sui file ai soli file coinvolti nel workflow corrente.",
              "L'autorizzazione dell'interfaccia contenitore di Google Workspace™ serve a mostrare la barra laterale di TransLay dentro Google Slides™.",
              "L'autorizzazione per richieste esterne serve affinché l'add-on comunichi in modo sicuro con il backend TransLay per task di traduzione, aggiornamento dei diritti, accesso e flussi di abbonamento.",
              "Le autorizzazioni per email e avatar dell'account Google servono per identificare l'accesso, mostrare l'account corrente, collegare gli abbonamenti e gestire l'assistenza post-vendita."
            ]
          },
          {
            title: "5. Come concedere queste autorizzazioni",
            paragraphs: [
              "Dopo aver installato TransLay dal Google Workspace Marketplace, al primo avvio in Google Slides™ Google ti chiederà di completare il processo di autorizzazione. In pratica, installi l'add-on, apri una qualsiasi presentazione Google Slides™, vai su Estensioni, avvii TransLay e segui il prompt verso la pagina di conferma delle autorizzazioni Google.",
              "Nella pagina di conferma, accedi con l'account Google che intendi usare con TransLay. Se Google mostra una casella \"seleziona tutto\", seleziona le autorizzazioni necessarie e fai clic su Consenti o Conferma. Senza queste autorizzazioni necessarie, TransLay non potrà leggere correttamente i documenti, eseguire la traduzione, creare file di destinazione, scrivere i risultati o completare i flussi di accesso e abbonamento."
            ]
          },
          {
            title: "6. Come usiamo queste informazioni",
            paragraphs: [
              "Queste informazioni vengono usate solo per completare la traduzione richiesta, mostrare lo stato di accesso corrente, collegare abbonamenti e quote, gestire fatturazione e rimborsi, rispondere alle richieste di assistenza, prevenire abusi e mantenere stabile il servizio. Non le usiamo per pubblicità, profilazione, raccomandazioni di marketing o analisi comportamentale. Inoltre non usiamo il contenuto dei tuoi documenti per addestrare i nostri modelli."
            ]
          },
          {
            title: "7. Servizi di terze parti",
            paragraphs: [
              "Per far funzionare TransLay, quando necessario ci affidiamo a un numero limitato di servizi di terze parti, tra cui Google Workspace™ e Google Cloud per hosting, accesso ai documenti e operatività del servizio, fornitori AI e cloud per l'elaborazione della traduzione, e Paddle per pagamenti, tasse e rimborsi. Questi servizi partecipano solo nella misura necessaria a fornire le funzioni attuali."
            ]
          },
          {
            title: "8. Conservazione ed eliminazione",
            paragraphs: [
              "Il nostro obiettivo è conservare il minor numero possibile di informazioni per il minor tempo possibile. Testo, traduzioni, comments e notes collegati al contenuto tradotto vengono eliminati dal database e dalla cache subito dopo la fine del task. Una piccola quantità di informazioni necessarie per account, abbonamenti, ordini o conformità può tuttavia essere conservata quando strettamente necessario per confermare diritti, elaborare rimborsi o rispondere a richieste legittime.",
              "Se vuoi eliminare le informazioni personali collegate al tuo account, o capire quali registrazioni minime siano ancora presenti, contatta <strong>support@example.com</strong>. Tieni presente che, se richiedi l'eliminazione dei record necessari a dimostrare e ripristinare i diritti di abbonamento, potremmo non essere più in grado di ripristinare tali diritti in seguito."
            ]
          },
          {
            title: "9. I tuoi diritti e le tue scelte",
            paragraphs: [
              "Puoi smettere di usare TransLay in qualsiasi momento. Puoi anche annullare un abbonamento, uscire dall'account o contattarci per richieste relative alla privacy. Quando la legge applicabile ti riconosce diritti di accesso, rettifica, cancellazione o limitazione del trattamento, gestiremo le richieste valide secondo le regole applicabili."
            ]
          },
          {
            title: "10. Aggiornamenti della policy e contatti",
            paragraphs: [
              "Se cambiano il prodotto, il flusso di pagamento o gli obblighi legali, potremmo aggiornare questa Informativa sulla privacy. Le versioni aggiornate saranno pubblicate nelle pagine pertinenti del sito ufficiale. Per domande su privacy, trattamento dei dati o sicurezza, invia un'email a <strong>support@example.com</strong>."
            ]
          }
        ]
      }
