              "La unidad mínima para solicitar un reembolso de créditos a consumo es 1 página. El reembolso se calcula solo sobre los créditos a consumo no usados; los créditos ya consumidos por tareas de traducción completadas correctamente no son reembolsables.",
              "Paddle procesa los reembolsos según las transacciones de compra originales. Si una solicitud de reembolso cubre créditos procedentes de varias compras a consumo, TransLay puede dividirla en varios reembolsos de Paddle según las transacciones originales. El importe total del reembolso no cambiará, pero podrías recibir varios emails de notificación de reembolso de Paddle.",
