              "Si más adelante vuelves a iniciar la traducción del mismo documento al mismo idioma, la trataremos como una nueva tarea independiente. Como no conservamos los contenidos ni las traducciones anteriores, no reutilizamos directamente el resultado previo y la nueva tarea se facturará íntegramente según las reglas de esa tarea.",
              "No usamos tu información para publicidad, atribución publicitaria, creación de perfiles de usuario ni análisis de comportamiento. No vendemos tus datos y no seguimos tus actividades en otros sitios, documentos o productos solo porque uses TransLay.",
              "No conservamos el número completo de tarjeta, el número completo de cuenta bancaria ni otras credenciales de pago completas. Los pagos son gestionados por Paddle; nosotros solo recibimos la información mínima de resultado necesaria para pedidos y soporte posventa."
