              "Você mantém todos os direitos sobre seus documentos, apresentações e respectivos conteúdos. Para concluir uma solicitação de tradução iniciada por você, você autoriza o TransLay, no escopo necessário para operar o serviço, a acessar o arquivo selecionado, ler o conteúdo a ser traduzido, gerar a tradução e gravar o resultado no documento original ou em um novo documento de destino conforme suas instruções. Essa autorização existe apenas para prestar o serviço e não transfere a nós a propriedade do seu conteúdo.",
              "O texto original, as traduções, comments e notes relacionados à tarefa de tradução são processados apenas brevemente enquanto a tarefa está em execução. Quando a tarefa termina, esse conteúdo é removido imediatamente do nosso banco de dados e do cache e não é mantido como seu backup em nuvem. Por isso, guarde por conta própria o documento de destino traduzido. Se depois você solicitar novamente a tradução do mesmo documento para o mesmo idioma, trataremos isso como uma nova tarefa independente e cobraremos integralmente conforme as regras dessa tarefa."
