      privacy: {
        title: "TransLay integritetspolicy",
        last_updated: "Senast uppdaterad: 2026-04-23",
        intro: [
          "Vi ser \"samla in mindre, spara mindre, exponera mindre\" som en grundprincip för TransLay. När du använder TransLay behandlar vi bara den minsta information som krävs för att översättning, inloggning, prenumeration och efterköpssupport ska fungera. Det som inte bör samlas in eller inte bör sparas långsiktigt försöker vi låta bli att röra. Denna integritetspolicy förklarar hur TransLay behandlar denna information."
        ],
        sections: [
          {
            title: "1. Våra integritetsprinciper",
            paragraphs: [
              "TransLays kärnprincip är enkel: vi behandlar bara den information som behövs för att slutföra den tjänst du aktivt begär. Vi samlar inte in information som saknar koppling till tjänsten, använder inte information för annonsering, bygger inte användarprofiler och gör ingen beteendeanalys. Särskilt för brödtext, översättningar, comments och notes i dina dokument följer vi strikt minimering och behåller inte detta innehåll långsiktigt i databaser, cache eller applikationsloggar."
            ]
          },
          {
            title: "2. Vilken minimiinformation vi behandlar för att tillhandahålla tjänsten",
            paragraphs: [
              "Vi kan behandla grundläggande information om ditt Google-konto, till exempel Google-konto-ID, e-postadress, visningsnamn och avatar, för att bekräfta din identitet, koppla prenumerationer och kvoter till rätt konto, visa aktuellt inloggat konto och ge efterköpssupport.",
              "Vi behandlar Google Slides™-innehåll som du uttryckligen väljer för översättning endast efter att du aktivt har startat en översättningsuppgift, och endast för att slutföra den översättningen och skriva tillbaka resultatet.",
              "Vi behandlar också den minsta uppgifts- och kvotinformation som krävs för att visa uppgiftsförlopp, reglera användning, kontrollera faktureringsfrågor och ge support, till exempel Task ID, uppgiftsstatus, sidförbrukning, tidsstämplar och begränsad felsökningsmetadata.",
              "Om du köper en plan eller credits behandlar vi minsta order- och prenumerationsinformation som krävs för att bekräfta dina rättigheter, till exempel betalningsstatus, ordernummer, köp- eller återbetalningstidpunkt och prenumerationsstatus. Fullständiga kortuppgifter behandlas av Paddle och sparas inte av oss.",
              "För webbplatssessioner använder vi bara den minsta sessionsinformation som krävs för att den officiella webbplatsen och prenumerationssidorna ska fungera. Cookies sparar endast ett opakt session-id och sparar inte direkt läsbar klartext som e-postadress, plan eller kvot."
            ]
          },
          {
            title: "3. Vad vi inte sparar eller samlar in",
            paragraphs: [
              "Vi sparar inte klartext av dokumentinnehåll, översättningsresultat, comments eller notes i databaser, cache eller loggar. När en översättningsuppgift är slut raderas detta innehåll omedelbart från våra databaser och cache och behålls inte som dokumentbackup. Se därför till att själv bevara det översatta måldokumentet.",
              "Om du senare begär översättning av samma dokument till samma språk igen behandlar vi det som en ny separat uppgift. Eftersom vi inte sparar tidigare dokumentinnehåll eller översättning återanvänder vi inte det tidigare resultatet direkt, och den nya uppgiften debiteras fullt enligt sina regler.",
              "Vi använder inte din information för annonsering, annonsspårning, användarprofilering eller beteendeanalys. Vi säljer inte dina data och spårar inte din aktivitet på andra webbplatser, i andra dokument eller i andra produkter bara för att du använder TransLay.",
              "Vi sparar inte fullständiga kortnummer, bankkontonummer eller andra fullständiga betalningsuppgifter. Betalningar behandlas av Paddle; vi tar bara emot den minsta resultatinformation som krävs för order och efterköpssupport."
            ]
          },
          {
            title: "4. Varför Google-behörigheter behövs",
            paragraphs: [
              "TransLay är ett Google Workspace™-tillägg. För att fungera korrekt i Google Slides™ begär vi bara behörigheter som direkt behövs inom produktens nuvarande omfattning.",
              "Google Slides™-behörigheten används för att läsa presentationen som ska översättas och skriva tillbaka översättningen till originalfilen eller måldokumentet. Utan denna behörighet kan TransLay inte läsa innehållet eller slutföra tillbakaskrivningen.",
              "Google Drive™-behörigheten används för att identifiera den aktuella presentationen, skapa användarägda kopior i läget \"utdata till ny fil\", placera måldokumentet på rätt plats och hantera tillfällig åtkomst under uppgiften. Utan denna behörighet kan vissa kopierings- och tillbakaskrivningsflöden inte fungera stabilt.",
              "Google Drive™ file-behörigheten hjälper oss att begränsa filåtgärder så långt som möjligt till de filer som ingår i det aktuella arbetsflödet.",
              "Google Workspace™-behörigheten för containergränssnittet används för att visa TransLays sidofält i Google Slides™.",
              "Behörigheten för externa begäranden används för att tillägget säkert ska kunna kommunicera med TransLays backend och slutföra översättningsuppgifter, rättighetsuppdateringar, inloggning och prenumerationsflöden.",
              "Behörigheter för Google-kontots e-postadress och avatar används för inloggningsidentifiering, visning av aktuellt konto, koppling av prenumerationer och hantering av efterköpssupport."
            ]
          },
          {
            title: "5. Hur du ger dessa behörigheter",
            paragraphs: [
              "När du har installerat TransLay via Google Workspace Marketplace uppmanar Google dig att slutföra behörighetsflödet första gången du öppnar och startar det i Google Slides™. Vanligtvis installerar du tillägget, öppnar valfri Google Slides™-presentation, går till Tillägg, startar TransLay och följer sedan uppmaningen till Googles behörighetsbekräftelsesida.",
              "På bekräftelsesidan loggar du in med det Google-konto du vill använda med TransLay. Om Google visar en kryssruta för \"välj alla\", markera de behörigheter som behövs och klicka sedan på Tillåt eller Bekräfta. Utan dessa nödvändiga behörigheter kan TransLay inte läsa dokument korrekt, utföra översättning, skapa måldokument, skriva tillbaka resultat eller slutföra inloggnings- och prenumerationsflöden."
            ]
          },
          {
            title: "6. Hur vi använder informationen",
            paragraphs: [
              "Denna information används endast för att utföra den översättning du begär, visa aktuell inloggningsstatus, koppla prenumerationer och credits, hantera fakturering och återbetalningar, besvara efterköpsfrågor, förhindra missbruk och säkerställa stabil drift av tjänsten. Vi använder inte informationen för annonsering, användarprofilering, marknadsföringsrekommendationer eller beteendeanalys. Vi använder inte heller ditt dokumentinnehåll för att träna våra egna modeller."
            ]
          },
          {
            title: "7. Tredjepartstjänster",
            paragraphs: [
              "För att driva TransLay använder vi vid behov ett litet antal tredjepartstjänster, till exempel Google Workspace™ och Google Cloud för hosting, dokumentåtkomst och tjänstedrift, AI- och molntjänstleverantörer för översättningsbearbetning samt Paddle för betalningar, skatt och återbetalningar. Dessa tjänster deltar endast i den omfattning som krävs för att tillhandahålla de aktuella funktionerna."
            ]
          },
          {
            title: "8. Lagring och radering",
            paragraphs: [
              "Vårt mål är att spara så lite information som möjligt under så kort tid som möjligt. Brödtext, översättningar, comments och notes som hör till översättningsinnehåll raderas omedelbart från databaser och cache när uppgiften är slut. En liten mängd information som krävs för kontokoppling, prenumerationer, order och efterlevnad kan fortsätta att sparas när det verkligen behövs för att bekräfta rättigheter, behandla återbetalningar eller svara på lagliga begäranden.",
              "Om du vill radera personuppgifter kopplade till ditt konto, eller vill veta vilka minsta poster som fortfarande finns kvar, kontakta <strong>support@example.com</strong>. Observera att om du begär radering av poster som krävs för att bevisa och återställa prenumerationsrättigheter kan vi senare kanske inte återställa motsvarande rättigheter åt dig."
            ]
          },
          {
            title: "9. Dina rättigheter och val",
            paragraphs: [
              "Du kan när som helst sluta använda TransLay. Du kan också säga upp en prenumeration, logga ut eller kontakta oss med integritetsrelaterade begäranden. I den utsträckning tillämplig lag ger dig rätt till åtkomst, rättelse, radering eller begränsning av behandling hanterar vi giltiga begäranden enligt gällande regler."
            ]
          },
          {
            title: "10. Policyuppdateringar och kontakt",
            paragraphs: [
              "Om produktformen, betalningsflödet eller juridiska skyldigheter ändras kan vi uppdatera denna integritetspolicy. Uppdaterade versioner publiceras på relevanta sidor på den officiella webbplatsen. Om du har frågor om integritet, databehandling eller säkerhet, mejla <strong>support@example.com</strong>."
            ]
          }
        ]
      }
